ParticleController pc;

void setup(){
  size(800,800);
  smooth();
  background(255);
  pc = new ParticleController();
  pc.pAddCircle(1000,100);
  pc.iAddCircle(100,100);
}

void draw(){
  pc.update(10);
  pc.display();
}

void keyPressed(){
  if(key == 'r'){
    background(255);
    pc = new ParticleController();
    pc.pAddCircle(1000,100);
    pc.iAddCircle(100,100);
  }
}
class Interference{

  mode; 
  mLoc;
  range;

  constructor(x, y){

    mLoc = new PVector(x,y);

    let randFloat = random(1);
    if(randFloat<0.5) mode = "ATTRACT";
    else mode = "REJECT";

    range = random(0,300);
  }
}
class Particle {

  mLoc;
  dir;

  constructor(x, y) {
    mLoc = new PVector(x, y);
  }

  function update(itf, force) {
    let distance = dist(itf.mLoc.x, itf.mLoc.y, mLoc.x, mLoc.y);
    if (distance<itf.range) {
      if (itf.mode.equals("ATTRACT")) {
        dir = PVector.sub(itf.mLoc, mLoc);
      }
      else {
        dir = PVector.sub(mLoc, itf.mLoc);
      }
      dir.normalize();
      dir.mult(force/distance);
      mLoc.add(dir);
    }
  }

  function display() {
    stroke(20, 20);
    point(mLoc.x, mLoc.y);
  }
}
class ParticleController{

  Interference [] interferences;
  Particle [] particles;

  constructor(){
  }

  function pAddCircle(amt, rRange){
    particles = new Array(amt);
    for(i=0;i<amt;i++){
      let r = rRange;
      let randDegree = random(360);
      let x = cos(radians(randDegree))*r+width/2;
      let y = sin(radians(randDegree))*r+height/2;
      particles[i] = new Particle(x,y);
    }
  }

  function iAddCircle(amt, rRange){
    interferences = new Array(amt);
    for(i=0;i<amt;i++){
      var r = rRange;
      var randDegree = random(360);
      var x = cos(radians(randDegree))*r+width/2;
      var y = sin(radians(randDegree))*r+height/2;
      interferences[i] = new Interference(x,y);
    }
  }

  function update(force){
    for(i=0;i<interferences.length;i++){
      for(j=0;j<particles.length;j++){
        particles[j].update(interferences[i],force);
      }
    }
  }

  function display(){
    for(i=0;i<particles.length;i++){
      particles[i].display();
    }
  }
}

